Sys.unsetenv("LC_ALL")
source("R/load.R");load_vetblcm()
source("modules/mod_layout.R",encoding="UTF-8");source("modules/mod_server.R",encoding="UTF-8")
shiny::testServer(app_server, {
  session$setInputs(language="zh",page="project",prior_type="alpha_beta",prior_parameter="Se1",prior_alpha=1,prior_beta=1,prior_lower=0,prior_upper=1,prior_mean=.5,prior_ess=2,mcmc_mode="preview",chains=4,adapt=300,burnin=500,iterations=1000,thin=1,seed=33,model_type="positive")
  session$setInputs(example=1);session$flushReact()
  stopifnot(nrow(rv$data)==6000,nrow(cross())==3,qc()$valid,rv$priors$Lower[1]==.5)
  stopifnot(identical(input$project_name,"SIMULATED EXAMPLE ONLY"),identical(input$specimen_preset,"custom"),identical(input$t1_rule_preset,"custom"),identical(input$t2_rule_preset,"custom"))
  stopifnot(nzchar(input$case_definition),nzchar(input$t1_positive_rule),nzchar(input$t2_positive_rule),identical(input$exclusion_preset,"none"),identical(input$sample_size_preset,"simulation"))
  stopifnot(all(nzchar(rv$populations$Definition)),all(nzchar(rv$populations$Rationale)),all(nzchar(rv$populations$Prior_source)))
  stopifnot(all(nzchar(rv$priors$Rationale)),all(nzchar(rv$priors$Source_population)),all(nzchar(rv$priors$Specimen)),all(nzchar(rv$priors$Estimate)),all(nzchar(rv$priors$Uncertainty)),all(nzchar(rv$priors$Applicability)),all(nzchar(rv$priors$Discount)))
  before<-sha256(rv$data);session$setInputs(language="en");session$flushReact();stopifnot(identical(sha256(rv$data),before))
  rv$scenarios[["Saved alternate"]]<-rv$priors;session$flushReact();stopifnot("Saved alternate" %in% names(rv$scenarios))
  session$setInputs(prior_parameter="Se2",prior_type="mean_ess",prior_mean=.8,prior_ess=50,prior_lower=0,prior_upper=1,prior_source="Independent example",prior_source_type="literature",prior_rationale="Testing UI save",prior_source_pop="Simulated",prior_uncertainty="Simulated")
  session$setInputs(save_prior=1);session$flushReact();stopifnot(abs(rv$priors$Alpha[3]-40)<1e-12,abs(rv$priors$Beta[3]-10)<1e-12)
